intro.snippet:
int knapsack(int i, int w){
    if(i < 0 || w <= 0) return 0;              // nothing left
    if(weight[i] > w) return knapsack(i-1, w);  // no room
    int take  = val[i] + knapsack(i-1, w - weight[i]);
    int leave = knapsack(i-1, w);
    return max(take, leave);
}
